import re

from phish_contracts.disclaimer import (
    DISCLAIMER_MARKDOWN,
    DISCLAIMER_TEXT,
    DISCLAIMER_TITLE,
    with_disclaimer_markdown,
)


def test_wording_is_the_fixed_contract():
    assert DISCLAIMER_TITLE == "AI-generated analysis: human review required"
    assert DISCLAIMER_TEXT == (
        "This output was generated by AI and can be wrong. A qualified human analyst must "
        "review it before any action is taken."
    )


def test_no_dashes():
    assert not re.search("[\u2014\u2013]", DISCLAIMER_MARKDOWN)


def test_markdown_has_bold_disclaimer_at_top_and_bottom_and_is_idempotent():
    once = with_disclaimer_markdown("## Verdict\nPhishing.\n")
    assert once.startswith(DISCLAIMER_MARKDOWN) and once.endswith(DISCLAIMER_MARKDOWN)
    assert DISCLAIMER_MARKDOWN.startswith("**")
    assert with_disclaimer_markdown(once) == once
    assert once.count(DISCLAIMER_TEXT) == 2


def test_markdown_adds_only_the_missing_end():
    footer_only = f"## Verdict\nx\n\n---\n\n{DISCLAIMER_MARKDOWN}"
    fixed = with_disclaimer_markdown(footer_only)
    assert fixed.startswith(DISCLAIMER_MARKDOWN) and fixed.count(DISCLAIMER_TEXT) == 2
    header_only = f"{DISCLAIMER_MARKDOWN}\n\n---\n\n## Verdict\nx"
    fixed = with_disclaimer_markdown(header_only)
    assert fixed.endswith(DISCLAIMER_MARKDOWN) and fixed.count(DISCLAIMER_TEXT) == 2


def test_markdown_append_on_empty_report():
    assert with_disclaimer_markdown("") == DISCLAIMER_MARKDOWN
